// Normalises the three entry points. The schedule always delivers. A manual
// run or a call from another workflow is a dry run unless it passes
// dry_run: false. Optional inputs: use_llm (default true) and date
// (YYYY-MM-DD, replaces today's Europe/Athens date for testing).
const input = $input.first()?.json ?? {};
const scheduled = Object.prototype.hasOwnProperty.call(input, 'timestamp')
  || Object.prototype.hasOwnProperty.call(input, 'Readable date');
const zone = 'Europe/Athens';
let now = DateTime.now().setZone(zone);
if (!scheduled && typeof input.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input.date)) {
  now = DateTime.fromISO(input.date, { zone }).set({ hour: now.hour, minute: now.minute, second: now.second });
}
return [{
  json: {
    job: "hf-models",
    scheduled,
    dry_run: scheduled ? false : input.dry_run !== false,
    use_llm: scheduled ? true : input.use_llm !== false,
    now: now.toISO(),
    today: now.toISODate(),
    yesterday: now.minus({ days: 1 }).toISODate(),
    month_start: now.startOf('month').toISODate(),
    weekday: now.setLocale('en').toFormat('cccc'),
  },
}];

const MAX_MESSAGE = 3500;

function decodeEntities(text) {
  return String(text ?? '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function oneLine(text, max) {
  let s = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (max && s.length > max) s = `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`;
  return s;
}

// Link text must not break the Markdown link.
function linkText(text) {
  return oneLine(text, 160).replace(/\[/g, '(').replace(/\]/g, ')');
}

function errorText(error) {
  if (!error) return 'unknown error';
  if (typeof error === 'string') return oneLine(error, 200);
  return oneLine(error.message || error.description || JSON.stringify(error), 200);
}

// Joins a heading and bullet lines, dropping trailing bullets that would
// exceed the Talk message budget.
function buildMessage(head, lines, footer) {
  let out = head;
  let dropped = 0;
  for (const line of lines) {
    if (out.length + line.length + 1 + (footer ? footer.length + 2 : 0) > MAX_MESSAGE) {
      dropped += 1;
      continue;
    }
    out += `\n${line}`;
  }
  if (dropped) out += `\n- …and ${dropped} more`;
  if (footer) out += `\n\n${footer}`;
  return out;
}

// New Hugging Face text models: created today or yesterday (Europe/Athens)
// and either GGUF or more than 100 downloads. Template only, no LLM.
const opt = $('Run options').first().json;
const sources = ['Trending text-generation', 'Trending GGUF'];
const failures = [];
const models = [];
for (const name of sources) {
  const res = $(name).first().json;
  let list = null;
  if (!res.error) {
    try { list = JSON.parse(res.data); } catch (e) { list = null; }
  }
  if (!Array.isArray(list)) {
    failures.push(`${name}: ${errorText(res.error || 'not a JSON list')}`);
    continue;
  }
  models.push(...list);
}
if (failures.length === sources.length) throw new Error(`Hugging Face API failed (${failures.join('; ')})`);

const SKIP = new Set([
  'text-to-image', 'image-to-image', 'unconditional-image-generation', 'image-to-video', 'text-to-video',
  'video-classification', 'text-to-speech', 'text-to-audio', 'audio-to-audio', 'automatic-speech-recognition',
  'audio-classification', 'voice-activity-detection', 'image-classification', 'image-segmentation',
  'object-detection', 'depth-estimation', 'image-to-3d', 'text-to-3d', 'mask-generation',
]);
const days = new Set([opt.today, opt.yesterday]);
const seen = new Set();
const rows = [];
for (const m of models) {
  if (!m || !m.id || seen.has(m.id)) continue;
  seen.add(m.id);
  const tags = Array.isArray(m.tags) ? m.tags : [];
  const created = DateTime.fromISO(String(m.createdAt || '')).setZone('Europe/Athens').toISODate();
  if (!days.has(created)) continue;
  if (SKIP.has(m.pipeline_tag) || tags.some((t) => SKIP.has(t))) continue;
  const gguf = tags.includes('gguf') || m.library_name === 'gguf';
  const downloads = Number(m.downloads || 0);
  const popular = downloads > 100;
  if (!gguf && !popular) continue;
  const qualified = gguf && popular ? 'GGUF + downloads' : gguf ? 'GGUF' : 'downloads';
  const base = (tags.find((t) => /^base_model:(?:quantized:|finetune:|adapter:|merge:)?[^:]+\/[^:]+$/.test(t)) || '')
    .replace(/^base_model:(?:quantized:|finetune:|adapter:|merge:)?/, '');
  const details = [
    qualified,
    downloads ? `${downloads.toLocaleString('en-US')} downloads` : null,
    m.pipeline_tag || null,
    base && base !== m.id ? `base ${base}` : null,
  ].filter(Boolean).join(' · ');
  rows.push(`- [${linkText(m.id)}](https://huggingface.co/${m.id}): ${details}`);
  if (rows.length >= 15) break;
}
if (!rows.length && failures.length) throw new Error(`Hugging Face API failed (${failures.join('; ')})`);
const footer = failures.length ? `_Incomplete: ${failures.join('; ')}_` : '';
const message = rows.length ? buildMessage(`### Hugging Face models, ${opt.today}\n`, rows, footer) : '';
return [{ json: { message, deliver: Boolean(message) && !opt.dry_run, dry_run: opt.dry_run, items: rows.length } }];

// Not delivered: a dry run, or nothing to report. Returned to a calling workflow.
const r = $input.first().json;
return [{ json: { ...r, delivered: false, reason: r.message ? 'dry run' : 'nothing to report' } }];

// This workflow is its own error workflow. Only failures of scheduled runs
// are posted; manual runs and dry runs show the error in n8n instead.
const e = $input.first().json;
const execution = e.execution || {};
const mode = String(execution.mode || '');
const node = execution.lastNodeExecuted || execution.error?.node?.name || 'unknown node';
const reason = String(execution.error?.message || execution.error?.description || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 300);
const message = `**${"hf-models"} digest failed** (n8n, node "${node}"): ${reason}`;
return [{ json: { message, deliver: mode === 'trigger' || mode === 'webhook', mode } }];
